export function partName(group, key, lang) {
  if (lang === 'ar' && AR_P[group + '.' + key] != null) return AR_P[group + '.' + key];
  const row = P[group]?.[key]; if (!row) return key;
  const i = ORDER.indexOf(lang); return row[i >= 0 ? i : 1] ?? row[1];
}

